import { Group, Mesh, PlaneGeometry, CylinderGeometry, Vector3, Color, Texture } from 'three/webgpu';
import {
	MeshStandardNodeMaterial,
	UVNode,
	FloatNode,
	OperatorNode,
	Vector2Node,
	LengthNode,
	MaxNode,
	AbsNode,
	SubNode,
	AddNode,
	ClampNode,
	OneMinusNode,
	MathNode,
	ColorNode,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as createCinematicPrimitive } from '@/primitives';
import { createText } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<Object>} textContent
 * @property {Object} cinematicPrimitives
 * @property {Object} position
 * @property {Object} rotation
 * @property {Object} scale
 */

/**
 * @typedef {Object} NodeContext
 * @property {function(string): Texture} textureLoader
 * @property {Object.<string, function(THREE.Object3D, any): void>} primitives
 * @property {Object} fontAtlas
 */

/**
 * Create three feature cards with hover lift and staggered entry.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	const root = new Group();
	root.position.set(
		config.position?.x ?? 0,
		config.position?.y ?? 0,
		config.position?.z ?? 0
	);
	root.rotation.set(
		config.rotation?.x ?? 0,
		config.rotation?.y ?? 0,
		config.rotation?.z ?? 0
	);
	root.scale.set(
		config.scale?.x ?? 1,
		config.scale?.y ?? 1,
		config.scale?.z ?? 1
	);

	// ---------- Shared Resources ----------
	const cardWidth = 1.5;
	const cardHeight = 1.9;
	const gap = 0.25;
	const totalWidth = 3 * cardWidth + 2 * gap; // 5.0
	const startX = -totalWidth / 2 + cardWidth / 2; // -1.75

	const texture = ctx.textureLoader('/prism-mock/home/nodes/feature-card.png');

	const baseMaterial = new MeshStandardNodeMaterial({
		map: texture,
		transparent: true,
		roughness: 0.6,
		metalness: 0.25,
		clearcoat: 0.15,
	});

	// Rounded‑corner alpha (optional – simple approximation)
	const radius = new FloatNode(0.06);
	const borderWidth = new FloatNode(0.006);
	const uvNode = new UVNode();
	const centeredUV = new SubNode(uvNode, new FloatNode(0.5));
	const absUV = new AbsNode(centeredUV);
	const inner = new SubNode(absUV, new SubNode(new FloatNode(0.5), radius));
	const maxInner = new MaxNode(inner, new FloatNode(0));
	const dist = new LengthNode(maxInner);
	const borderAlpha = new OneMinusNode(
		new ClampNode(
			new OperatorNode(dist, borderWidth, OperatorNode.SUB),
			new FloatNode(0),
			new FloatNode(1)
		)
	);
	baseMaterial.alphaNode = borderAlpha;
	baseMaterial.side = 2; // DoubleSide

	// ---------- Card Data ----------
	const cardsData = [
		{
			icon: '01',
			title: 'In-House Calibre',
			body: 'Every movement is designed, machined, and finished under one roof.',
		},
		{
			icon: '02',
			title: 'Five-Year Guarantee',
			body: 'Each piece is serviced free of charge for five years from delivery.',
		},
		{
			icon: '03',
			title: 'Hand-Finished Dials',
			body: 'Guilloche cut on a 1912 rose engine, one dial at a time.',
		},
	];

	const entryTimeline = gsap.timeline({ paused: true });
	const hoverTimelines = [];

	for (let i = 0; i < cardsData.length; i++) {
		const data = cardsData[i];

		// ----- Card Mesh -----
		const planeGeom = new PlaneGeometry(cardWidth, cardHeight);
		const cardMesh = new Mesh(planeGeom, baseMaterial.clone());
		cardMesh.position.set(startX + i * (cardWidth + gap), 0, 0);
		cardMesh.userData.originalY = cardMesh.position.y;
		root.add(cardMesh);

		// ----- Icon Disc -----
		const discRadius = 0.2; // 0.4 diameter
		const discHeight = 0.05;
		const discGeom = new CylinderGeometry(discRadius, discRadius, discHeight, 32);
		const discMaterial = new MeshStandardNodeMaterial({
			roughness: 0.55,
			metalness: 0.5,
			clearcoat: 0.2,
			color: new Color('#26262f'), // base metal colour
			emissive: new Color('#ff2a38'),
			emissiveIntensity: 1.6,
		});
		const discMesh = new Mesh(discGeom, discMaterial);
		discMesh.rotation.x = Math.PI / 2; // face forward
		discMesh.position.set(0, cardHeight / 2 - 0.3, 0.01);
		cardMesh.add(discMesh);

		// ----- Icon Glyph (MSDF) -----
		const glyphMesh = createText(ctx.fontAtlas, data.icon, {
			family: 'JetBrains Mono',
			size: 20,
			weight: 700,
			color: '#ff2a38',
			align: 'center',
			anchorX: 'center',
			anchorY: 'middle',
		});
		glyphMesh.scale.setScalar(0.02);
		glyphMesh.position.set(0, 0, discHeight / 2 + 0.001);
		discMesh.add(glyphMesh);

		// ----- Title Text -----
		const titleMesh = createText(ctx.fontAtlas, data.title, {
			family: 'Lora',
			size: 20,
			weight: 600,
			color: '#e8ecf2',
			align: 'center',
			anchorX: 'center',
			anchorY: 'top',
			lineHeight: 1.2,
		});
		titleMesh.scale.setScalar(0.018);
		titleMesh.position.set(0, discMesh.position.y - 0.25, 0.01);
		cardMesh.add(titleMesh);

		// ----- Body Text -----
		const bodyMesh = createText(ctx.fontAtlas, data.body, {
			family: 'JetBrains Mono',
			size: 13,
			weight: 400,
			color: '#e8ecf2',
			align: 'center',
			anchorX: 'center',
			anchorY: 'top',
			lineHeight: 1.5,
		});
		bodyMesh.scale.setScalar(0.014);
		bodyMesh.position.set(0, titleMesh.position.y - 0.18, 0.01);
		cardMesh.add(bodyMesh);

		// ----- Contact Shadow (simple ellipse plane) -----
		const shadowGeom = new PlaneGeometry(cardWidth * 0.9, 0.2);
		const shadowMat = new MeshStandardNodeMaterial({
			color: new Color('#000000'),
			transparent: true,
			opacity: 0.25,
			roughness: 1,
			metalness: 0,
			depthWrite: false,
		});
		const shadowMesh = new Mesh(shadowGeom, shadowMat);
		shadowMesh.rotation.x = -Math.PI / 2;
		shadowMesh.position.set(0, -cardHeight / 2 + 0.01, 0);
		cardMesh.add(shadowMesh);

		// ----- Entry Animation -----
		cardMesh.position.y += 0.2;
		cardMesh.scale.setScalar(1);
		cardMesh.visible = true;
		entryTimeline.fromTo(
			cardMesh.position,
			{ y: cardMesh.position.y },
			{ y: cardMesh.userData.originalY, duration: 0.5, ease: 'power2.out' },
			'i+=0.08'
		);
		entryTimeline.fromTo(
			cardMesh.material,
			{ opacity: 0 },
			{ opacity: 1, duration: 0.5, ease: 'power2.out' },
			'i+=0.08'
		);

		// ----- Hover Interaction -----
		const hoverTimeline = gsap.timeline({ paused: true });
		hoverTimeline.to(
			cardMesh.position,
			{ y: cardMesh.userData.originalY + 0.06, duration: 0.18, ease: 'power2.out' }
		);
		hoverTimeline.to(
			discMaterial,
			{ emissiveIntensity: 2.2, duration: 0.18, ease: 'power2.out' },
			0
		);
		hoverTimeline.to(
			shadowMat,
			{ opacity: 0.15, scaleY: 1.4, duration: 0.18, ease: 'power2.out' },
			0
		);
		hoverTimelines.push(hoverTimeline);

		// Attach handlers
		cardMesh.userData.handlers = {
			hoverEnter: () => {
				hoverTimeline.play(0);
			},
			hoverLeave: () => {
				hoverTimeline.reverse();
			},
		};
	}

	// Start entry animation
	entryTimeline.play();

	// ---------- Cleanup ----------
	root.userData.cleanup = () => {
		// stop all timelines
		entryTimeline.kill();
		hoverTimelines.forEach((tl) => tl.kill());

		// dispose meshes
		root.traverse((obj) => {
			if (obj.isMesh) {
				if (obj.geometry) obj.geometry.dispose();
				if (obj.material) {
					if (Array.isArray(obj.material)) {
						obj.material.forEach((m) => m.dispose());
					} else {
						obj.material.dispose();
					}
				}
				if (obj.userData.handlers) {
					obj.userData.handlers = {};
				}
			}
		});

		// dispose texture
		if (texture) texture.dispose();
	};

	// Apply any cinematic primitives listed (none for this node, but keep hook)
	if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
		for (const primitive of config.cinematicPrimitives) {
			if (ctx.primitives[primitive.name]) {
				ctx.primitives[primitive.name](root, primitive.params);
			}
		}
	}

	return root;
}
